export interface Refusal {
  error: string;
  current?: Person;
}

export interface PersonFields {
  name: string;
  grade: string;
  /** The date an edit's grade applies from (YYYY-MM-DD); blank takes the sheet's today. */
  gradeFrom?: string;
}

